// Some portions generated by Claude
type Card = { id: string; x?: number; y?: number };
type Link = { source: string; target: string };

/**
 * The cards an expansion may move: the expanded card (`anchorId`), the new cards and the expanded card's neighbours
 * always; then, up to about half of the cards drawn before, the cards a few links away (three for a big expansion, else
 * two) and the cards near the expanded card, nearest first. The expansion stays local but the affected cluster can
 * untangle itself and make room for the new cards.
 */
export function expansionMovableIds(nodes: readonly Card[], edges: readonly Link[], anchorId: string,
  newIds: ReadonlySet<string>): Set<string> {
  const neighborsById = new Map<string, Set<string>>();
  for (const edge of edges) {
    const sourceNeighbors = neighborsById.get(edge.source);
    if (sourceNeighbors) sourceNeighbors.add(edge.target);
    else neighborsById.set(edge.source, new Set([edge.target]));
    const targetNeighbors = neighborsById.get(edge.target);
    if (targetNeighbors) targetNeighbors.add(edge.source);
    else neighborsById.set(edge.target, new Set([edge.source]));
  }
  const mandatory = new Set([anchorId, ...newIds, ...(neighborsById.get(anchorId) ?? [])]);
  const depthById = new Map<string, number>();
  const frontier = [anchorId, ...newIds];
  frontier.forEach((id) => depthById.set(id, 0));
  const hopLimit = newIds.size >= 10 ? 3 : 2;
  for (let cursor = 0; cursor < frontier.length; cursor += 1) {
    const id = frontier[cursor];
    const depth = depthById.get(id) ?? 0;
    if (depth >= hopLimit) continue;
    (neighborsById.get(id) ?? []).forEach((neighborId) => {
      if (depthById.has(neighborId)) return;
      depthById.set(neighborId, depth + 1);
      frontier.push(neighborId);
    });
  }
  const anchor = nodes.find((node) => node.id === anchorId);
  const spatialRadius = 420 + Math.min(180, newIds.size * 12);
  const candidates = nodes
    .filter((node) => !mandatory.has(node.id))
    .map((node) => ({
      id: node.id,
      depth: depthById.get(node.id) ?? Number.POSITIVE_INFINITY,
      distance:
        anchor?.x === undefined || anchor.y === undefined || node.x === undefined || node.y === undefined
          ? Number.POSITIVE_INFINITY
          : Math.hypot(node.x - anchor.x, node.y - anchor.y),
    }))
    .filter((candidate) => candidate.depth <= hopLimit || candidate.distance <= spatialRadius)
    .sort((left, right) => left.depth - right.depth || left.distance - right.distance || left.id.localeCompare(right.id));
  // The new cards, and up to about half of the cards drawn before (at least 32).
  const drawn = nodes.length - newIds.size;
  const movableLimit = Math.max(mandatory.size, newIds.size + Math.min(drawn, Math.max(32, Math.ceil(drawn * 0.55))));
  const movable = new Set(mandatory);
  for (const candidate of candidates) {
    if (movable.size >= movableLimit) break;
    movable.add(candidate.id);
  }
  return movable;
}
